// working calculator — Area of a square (jahdb demo program)
function areaSquare(s){
return s*s;
}
console.log("areaSquare(5) = "+areaSquare(5));

// working calculator — Area of a rectangle (jahdb demo program)
function areaRect(l,w){
return l*w;
}
console.log("areaRect(4,7) = "+areaRect(4,7));

// working calculator — Area of a triangle (jahdb demo program)
function areaTri(b,h){
return b*h/2;
}
console.log("areaTri(10,6) = "+areaTri(10,6));

// working calculator — Heron triangle area (jahdb demo program)
function areaHeron(a,b,c){
var s=(a+b+c)/2;return Math.sqrt(s*(s-a)*(s-b)*(s-c));
}
console.log("areaHeron(3,4,5) = "+areaHeron(3,4,5));

// working calculator — Area of an equilateral triangle (jahdb demo program)
function areaEqTri(s){
return Math.sqrt(3)/4*s*s;
}
console.log("areaEqTri(2) = "+areaEqTri(2));

// working calculator — Area of a parallelogram (jahdb demo program)
function areaPara(b,h){
return b*h;
}
console.log("areaPara(8,3) = "+areaPara(8,3));

// working calculator — Area of a trapezoid (jahdb demo program)
function areaTrap(a,b,h){
return (a+b)/2*h;
}
console.log("areaTrap(4,6,5) = "+areaTrap(4,6,5));

// working calculator — Area of a rhombus (jahdb demo program)
function areaRhombus(d1,d2){
return d1*d2/2;
}
console.log("areaRhombus(6,8) = "+areaRhombus(6,8));

// working calculator — Area of a kite (jahdb demo program)
function areaKite(d1,d2){
return d1*d2/2;
}
console.log("areaKite(5,10) = "+areaKite(5,10));

// working calculator — Area of a regular polygon (jahdb demo program)
function areaPoly(p,a){
return 0.5*p*a;
}
console.log("areaPoly(30,4.33) = "+areaPoly(30,4.33));

// working calculator — Area of a circle (jahdb demo program)
function areaCircle(r){
return Math.PI*r*r;
}
console.log("areaCircle(3) = "+areaCircle(3));

// working calculator — Area of a circular sector (jahdb demo program)
function areaSector(r,deg){
return deg/360*Math.PI*r*r;
}
console.log("areaSector(4,90) = "+areaSector(4,90));

// working calculator — Area of an ellipse (jahdb demo program)
function areaEllipse(a,b){
return Math.PI*a*b;
}
console.log("areaEllipse(5,3) = "+areaEllipse(5,3));

// working calculator — Area of an annulus (jahdb demo program)
function areaAnnulus(R,r){
return Math.PI*(R*R-r*r);
}
console.log("areaAnnulus(5,3) = "+areaAnnulus(5,3));

// working calculator — Perimeter of a square (jahdb demo program)
function perimSquare(s){
return 4*s;
}
console.log("perimSquare(5) = "+perimSquare(5));

// working calculator — Perimeter of a rectangle (jahdb demo program)
function perimRect(l,w){
return 2*(l+w);
}
console.log("perimRect(4,7) = "+perimRect(4,7));

// working calculator — Circumference of a circle (jahdb demo program)
function circumference(r){
return 2*Math.PI*r;
}
console.log("circumference(3) = "+circumference(3));

// working calculator — Arc length (jahdb demo program)
function arcLength(r,deg){
return deg/360*2*Math.PI*r;
}
console.log("arcLength(10,36) = "+arcLength(10,36));

// working calculator — Surface area of a cube (jahdb demo program)
function saCube(s){
return 6*s*s;
}
console.log("saCube(3) = "+saCube(3));

// working calculator — Surface area of a rectangular prism (jahdb demo program)
function saPrism(l,w,h){
return 2*(l*w+l*h+w*h);
}
console.log("saPrism(2,3,4) = "+saPrism(2,3,4));

// working calculator — Surface area of a cylinder (jahdb demo program)
function saCylinder(r,h){
return 2*Math.PI*r*(r+h);
}
console.log("saCylinder(2,5) = "+saCylinder(2,5));

// working calculator — Surface area of a cone (jahdb demo program)
function saCone(r,slant){
return Math.PI*r*(r+slant);
}
console.log("saCone(3,5) = "+saCone(3,5));

// working calculator — Surface area of a sphere (jahdb demo program)
function saSphere(r){
return 4*Math.PI*r*r;
}
console.log("saSphere(3) = "+saSphere(3));

// working calculator — Surface area of a square pyramid (jahdb demo program)
function saPyramid(b,s){
return b*b+2*b*s;
}
console.log("saPyramid(4,6) = "+saPyramid(4,6));

// working calculator — Volume of a cube (jahdb demo program)
function volCube(s){
return s*s*s;
}
console.log("volCube(3) = "+volCube(3));

// working calculator — Volume of a rectangular prism (jahdb demo program)
function volPrism(l,w,h){
return l*w*h;
}
console.log("volPrism(2,3,4) = "+volPrism(2,3,4));

// working calculator — Volume of a cylinder (jahdb demo program)
function volCylinder(r,h){
return Math.PI*r*r*h;
}
console.log("volCylinder(2,5) = "+volCylinder(2,5));

// working calculator — Volume of a cone (jahdb demo program)
function volCone(r,h){
return Math.PI*r*r*h/3;
}
console.log("volCone(3,6) = "+volCone(3,6));

// working calculator — Volume of a sphere (jahdb demo program)
function volSphere(r){
return 4/3*Math.PI*r*r*r;
}
console.log("volSphere(3) = "+volSphere(3));

// working calculator — Volume of a square pyramid (jahdb demo program)
function volPyramid(b,h){
return b*b*h/3;
}
console.log("volPyramid(4,9) = "+volPyramid(4,9));

// working calculator — Volume of a triangular pyramid (jahdb demo program)
function volTriPyr(baseArea,h){
return baseArea*h/3;
}
console.log("volTriPyr(10,6) = "+volTriPyr(10,6));

// working calculator — Volume of an ellipsoid (jahdb demo program)
function volEllipsoid(a,b,c){
return 4/3*Math.PI*a*b*c;
}
console.log("volEllipsoid(3,2,1) = "+volEllipsoid(3,2,1));

// working calculator — Volume of a torus (jahdb demo program)
function volTorus(R,r){
return 2*Math.PI*Math.PI*R*r*r;
}
console.log("volTorus(10,2) = "+volTorus(10,2));

// working calculator — Volume of a hemisphere (jahdb demo program)
function volHemi(r){
return 2/3*Math.PI*r*r*r;
}
console.log("volHemi(3) = "+volHemi(3));

// working calculator — Volume of a frustum (jahdb demo program)
function volFrustum(R,r,h){
return Math.PI*h*(R*R+R*r+r*r)/3;
}
console.log("volFrustum(4,2,6) = "+volFrustum(4,2,6));

// working calculator — Pythagorean theorem (jahdb demo program)
function pythag(a,b){
return Math.sqrt(a*a+b*b);
}
console.log("pythag(3,4) = "+pythag(3,4));

// working calculator — Distance formula (jahdb demo program)
function distance(x1,y1,x2,y2){
return Math.hypot(x2-x1,y2-y1);
}
console.log("distance(0,0,3,4) = "+distance(0,0,3,4));

// working calculator — Midpoint formula (jahdb demo program)
function midpoint(x1,y1,x2,y2){
return [(x1+x2)/2,(y1+y2)/2];
}
console.log("midpoint(0,0,4,6) = "+JSON.stringify(midpoint(0,0,4,6)));

// working calculator — Slope of a line (jahdb demo program)
function slope(x1,y1,x2,y2){
return (y2-y1)/(x2-x1);
}
console.log("slope(0,0,4,2) = "+slope(0,0,4,2));

// working calculator — Circle equation check (jahdb demo program)
function circleCheck(x,y,h,k,r){
var d=Math.hypot(x-h,y-k);return Math.abs(d-r)<1e-9?"on circle":"distance "+d;
}
console.log("circleCheck(3,4,0,0,5) = "+circleCheck(3,4,0,0,5));

// working calculator — Quadratic formula (jahdb demo program)
function quadratic(a,b,c){
var d=b*b-4*a*c;if(d<0)return "no real roots";return [(-b+Math.sqrt(d))/(2*a),(-b-Math.sqrt(d))/(2*a)];
}
console.log("quadratic(1,-5,6) = "+JSON.stringify(quadratic(1,-5,6)));

// working calculator — Triangle angle sum (jahdb demo program)
function triAngleSum(a,b){
return 180-a-b;
}
console.log("triAngleSum(60,70) = "+triAngleSum(60,70));

// working calculator — Polygon interior angle (jahdb demo program)
function polyAngle(n){
return (n-2)*180/n;
}
console.log("polyAngle(6) = "+polyAngle(6));

// working calculator — Diagonal of a rectangle (jahdb demo program)
function diagRect(l,w){
return Math.hypot(l,w);
}
console.log("diagRect(3,4) = "+diagRect(3,4));

// working calculator — Space diagonal of a cube (jahdb demo program)
function diagCube(s){
return s*Math.sqrt(3);
}
console.log("diagCube(2) = "+diagCube(2));

// working calculator — 30-60-90 triangle ratio (jahdb demo program)
function tri3060(short){
return [short, short*Math.sqrt(3), 2*short];
}
console.log("tri3060(1) = "+JSON.stringify(tri3060(1)));

// working calculator — 45-45-90 triangle ratio (jahdb demo program)
function tri4545(leg){
return [leg, leg, leg*Math.sqrt(2)];
}
console.log("tri4545(1) = "+JSON.stringify(tri4545(1)));

// working calculator — Lateral area of a cylinder (jahdb demo program)
function laCylinder(r,h){
return 2*Math.PI*r*h;
}
console.log("laCylinder(2,5) = "+laCylinder(2,5));

// working calculator — Lateral area of a cone (jahdb demo program)
function laCone(r,s){
return Math.PI*r*s;
}
console.log("laCone(3,5) = "+laCone(3,5));

// working calculator — Triangle inequality check (jahdb demo program)
function triValid(a,b,c){
return (a+b>c)&&(a+c>b)&&(b+c>a);
}
console.log("triValid(3,4,5) = "+triValid(3,4,5));
